require_once __DIR__.'/../config/session.php';
require_once __DIR__.'/../config/auth.php';
require_once __DIR__.'/../config/helper.php';
require_once __DIR__.'/../includes/ujian_nilai_tools.php';
check_access([2]);$db=Database::getInstance();
$q=$db->prepare('SELECT id FROM guru WHERE user_id=?');$q->execute([$_SESSION['user_id']]);$guru=(int)$q->fetchColumn();$user=(int)$_SESSION['user_id'];
$pid=(int)($_GET['pengajaran_id']??0);$exam=(int)($_GET['ujian_id']??0);$panel=($_GET['panel']??'impor')==='remedial'?'remedial':'impor';
$error='';$success=$_SESSION['uhn_success']??'';unset($_SESSION['uhn_success']);
try{$context=uhn_context($db,$guru,$pid,$exam);}catch(Throwable $e){http_response_code(403);exit('UH tidak tersedia untuk Anda.');}
$url='ujian_nilai.php?'.http_build_query(['pengajaran_id'=>$pid,'ujian_id'=>$exam,'panel'=>$panel]);
if(($_GET['format']??'')==='template'){
    $workbook=uhn_template_xlsx($context);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="nilai_UH_'.$context['selected']['nomor'].'_'.$exam.'.xlsx"');header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');header('Content-Length: '.strlen($workbook));echo $workbook;exit;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        if(!is_string($_POST['csrf_token']??null)||!verify_csrf($_POST['csrf_token']))throw new RuntimeException('Sesi keamanan berakhir. Muat ulang halaman.');
        $action=$_POST['action']??'';
        if($action==='preview'){
            unset($_SESSION['uhn_import']);$file=$_FILES['file_nilai']??[];
            if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_uploaded_file($file['tmp_name']??'')||($file['size']??0)>5*1024*1024||!in_array(strtolower(pathinfo($file['name']??'',PATHINFO_EXTENSION)),['xls','xlsx'],true))throw new RuntimeException('Unggah file .xlsx atau .xls maksimal 5 MB.');
            $book=ni_read_excel($file['tmp_name']);$rows=uhn_preview($context,$book['rows']);
            $_SESSION['uhn_import']=['guru'=>$guru,'user'=>$user,'pid'=>$pid,'exam'=>$exam,'expires'=>time()+900,'token'=>bin2hex(random_bytes(24)),'rows'=>$rows];
        }elseif($action==='import'){
            $plan=$_SESSION['uhn_import']??[];
            if(!is_string($_POST['import_token']??null)||!isset($plan['token'])||!hash_equals($plan['token'],$_POST['import_token']))throw new RuntimeException('Pratinjau tidak valid. Unggah ulang file.');
            $count=uhn_import($db,$guru,$user,$pid,$exam,$plan);unset($_SESSION['uhn_import']);$_SESSION['uhn_success']=$count.' nilai UH berhasil diimpor.';header('Location: '.$url);exit;
        }elseif($action==='remedial'){
            if(!is_array($_POST['nilai_remedial']??null)||!is_array($_POST['catatan_remedial']??null))throw new RuntimeException('Format nilai tidak valid.');
            $count=uhn_remedial($db,$guru,$user,$pid,$exam,$_POST['nilai_remedial'],$_POST['catatan_remedial']);$_SESSION['uhn_success']=$count.' nilai remedial tersimpan. Rekap UH dan Rekap Nilai diperbarui.';header('Location: '.$url);exit;
        }elseif($action==='cancel'){
            $reason=$_POST['alasan']??'';if(!is_string($reason))throw new RuntimeException('Alasan tidak valid.');
            uhn_cancel($db,$guru,$user,$pid,$exam,(int)($_POST['remedial_id']??0),$reason);$_SESSION['uhn_success']='Remedial dibatalkan. Nilai dihitung ulang dan riwayat tetap tersimpan.';header('Location: '.$url);exit;
        }elseif($action==='create'){
            $child=uhn_create($db,$guru,$user,$pid,$exam,$_POST);$_SESSION['uhn_success']='Ujian remedial dibuat dan langsung tampil hanya ke siswa peserta. Soal CBT disalin dari UH asal dan dapat dikelola dari daftar ulangan.';header('Location: '.$url);exit;
        }else throw new RuntimeException('Aksi tidak valid.');
    }catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Nilai UH: '.$e->getMessage());$error=$e instanceof PDOException?'Data gagal diproses. Silakan muat ulang halaman.':$e->getMessage();}
    $context=uhn_context($db,$guru,$pid,$exam);
}
$selected=$context['selected'];$ready=uh_remedial_ready($db);$history=$ready?uhn_history($db,$exam):[];$initial=[];foreach($history as $attempt)if(!isset($initial[$attempt['siswa_id']]))$initial[$attempt['siswa_id']]=$attempt['nilai_awal'];
$eligible=[];$names=[];foreach($context['students'] as $s){$names[$s['id']]=$s['nama_lengkap'];if($selected['selesai']&&!$s['pending']&&$s['status']!=='Berlangsung'&&($s['nilai']!==null||$s['status']!=='Selesai')&&(float)($s['nilai']??0)<75)$eligible[]=$s;}
$plan=$_SESSION['uhn_import']??null;if($plan&&(($plan['exam']??0)!==$exam||($plan['pid']??0)!==$pid||($plan['user']??0)!==$user||($plan['expires']??0)<time()))$plan=null;
$assignments=[];if($ready){$q=$db->prepare('SELECT u.id,u.nama_ujian,u.waktu_mulai,u.waktu_selesai,(SELECT COUNT(*) FROM sesi_ujian se WHERE se.ujian_id=u.id AND se.status=\'Selesai\') selesai,(SELECT COUNT(*) FROM ujian_harian_penerima p WHERE p.ujian_id=u.id) peserta FROM ujian_harian_remedial r JOIN ujian u ON u.id=r.ujian_id WHERE r.ujian_asal_id=? ORDER BY u.id DESC');$q->execute([$exam]);$assignments=$q->fetchAll();}
$hidden=static function(string $action):void{echo '<input type="hidden" name="csrf_token" value="'.sanitize($_SESSION['csrf_token']).'"><input type="hidden" name="action" value="'.$action.'">';};
require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/sidebar.php';
