<div class="uh-list-heading"><a href="ujian.php?rekap_pengajaran=<?= $pid ?>#rekap-ujian" class="btn btn-outline-secondary"><i class="fa-solid fa-arrow-left me-1" aria-hidden="true"></i>Kembali ke rekap UH</a><a href="rekap_nilai_guru.php?pengajaran_id=<?= $pid ?>" class="btn btn-outline-primary">Rekap Nilai</a></div>
