<?php if($plan):$count=count(array_filter($plan['rows'],static fn($r)=>$r['ready']));$invalid=count(array_filter($plan['rows'],static fn($r)=>$r['invalid'])); ?>
<section class="card p-3 p-md-4"><h2 class="h6">Pratinjau nilai</h2><p class="small"><?= $count ?> nilai siap diimpor. <?= count($plan['rows'])-$count ?> nilai dilewati atau perlu diperbaiki.</p><div class="table-responsive"><table class="table uh-recap-table"><thead><tr><th>Siswa</th><th>Nilai Excel</th><th>Hasil pemeriksaan</th></tr></thead><tbody><?php foreach($plan['rows'] as $r): ?><tr><th scope="row"><?= sanitize($r['nama']) ?></th><td><?= sanitize($r['raw']) ?></td><td class="<?= $r['ready']?'text-success':($r['invalid']?'text-danger':'text-muted') ?>"><?= sanitize($r['reason']) ?></td></tr><?php endforeach ?></tbody></table></div><form method="post" class="mt-3"><?php $hidden('import'); ?><input type="hidden" name="import_token" value="<?= sanitize($plan['token']) ?>"><button class="btn btn-primary" <?= !$count||$invalid?'disabled':'' ?>>Konfirmasi impor <?= $count ?> nilai</button></form></section><?php endif ?>
<?php else: ?>
<?php if(!$ready): ?><div class="alert alert-warning">Migrasi remedial UH belum diaktifkan.</div><?php else: ?>
